    fp2 = os.path.join(root, 'beh', 'Unsupervised_pretraining_behavior')
    fp3 = os.path.join(root, 'spk')
    fp4 = os.path.join(root, 'retinotopy')
    fp5 = os.path.join(root, 'process_data')
