                fn = os.path.join(root, 'beh', 'Unsupervised_pretraining_behavior', k['name'])
            else:
                fn = os.path.join(root, 'beh', k['name'])
        elif k['name'].split('_')[-1] == 'areas.npz':
            fn = os.path.join(root, 'retinotopy', k['name'])
