            LickRaster[typ][tw] = {}
            ind = StimTrial[tw]
            issort = np.argsort(SoundPos[ind]) if typ=='sort_by_cue' else np.arange(ind.sum())

            LickRaster[typ][tw]['SoundPos'] = SoundPos[ind][issort]
