    bg[y.astype(int), x.astype(int)] = 1.0
    bg = ndimage.gaussian_filter(bg, sigma=1, truncate=sig_bg)>0 # create a background map
    bg = bg.astype(float)
    bg[bg==False] = np.nan # fill empty space with nan

