import numpy as np

# Check which behavioral files contain each session
import os
beh_dir = '/app/data/beh'
beh_files = [f for f in os.listdir(beh_dir) if f.startswith('Beh_') and f.endswith('.npy')]
print(f'Behavioral files: {len(beh_files)}')
for f in sorted(beh_files):
    size_mb = os.path.getsize(os.path.join(beh_dir, f)) / 1e6
    print(f'  {f}: {size_mb:.1f} MB')

# Map each unique session to which beh files it appears in
session_to_beh_files = {}
for f in sorted(beh_files):
    beh = np.load(os.path.join(beh_dir, f), allow_pickle=True).item()
    for key in beh.keys():
        if key not in session_to_beh_files:
            session_to_beh_files[key] = []
        session_to_beh_files[key].append(f)

print(f'\nTotal unique session keys across beh files: {len(session_to_beh_files)}')

# Check sessions that appear in multiple files
multi = {k: v for k, v in session_to_beh_files.items() if len(v) > 1}
print(f'Sessions in multiple beh files: {len(multi)}')
for k, v in list(multi.items())[:5]:
    print(f'  {k}: {v}')

# Check sessions that appear in only one file
single = {k: v for k, v in session_to_beh_files.items() if len(v) == 1}
print(f'Sessions in single beh file: {len(single)}')
for k, v in list(single.items())[:5]:
    print(f'  {k}: {v}')
